CREATE TABLE public.channel ( id BIGSERIAL NOT NULL, name VARCHAR(100) NOT NULL, type VARCHAR(50) NOT NULL, description TEXT, is_active BOOLEAN NOT NULL DEFAULT true, created_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,
CONSTRAINT pk_channel PRIMARY KEY (id), CONSTRAINT uk_channel_name UNIQUE (name) );
CREATE INDEX idx_channel_type ON public.channel(type);
